# frozen_string_literal: true

require "rails_helper"

class DependencyGraphSnapshotsClientStub < Twirp::Client
  client_for Github::DependencySnapshotsApi::DependabotServiceService

  PATH = "github.dependency_snapshots_api.DependabotService/CreateDependabotSnapshot"

  def initialize(path, &block)
    super(Faraday.new do |conn|
      conn.adapter :test do |stub|
        stub.post(path, &block)
      end
    end)
  end

  # Create a stubbed client with a specific result and message
  def self.with_result(result:, msg:)
    new(PATH) do |_req|
      response = Github::DependencySnapshotsApi::CreateDependabotSnapshotResponse.new(
        snapshot_id: 123,
        created_at: Time.now.utc,
        result: result,
        message: msg
      )

      [
        200,
        { "Content-Type" => "application/protobuf" },
        Github::DependencySnapshotsApi::CreateDependabotSnapshotResponse.encode(response),
      ]
    end
  end
end

RSpec.describe DependencyGraph::Snapshots do
  describe "#create_dependabot_snapshot" do
    let(:payload) do
      ActiveSupport::HashWithIndifferentAccess.new(
        version: 1,
        sha: "ce587453ced02b1526dfb4cb910479d431683101",
        ref: "refs/heads/main",
        job: {
          correlator: "dependabot-npm",
          id: "451",
        },
        detector: {
          name: "dependabot",
          version: "1.0.0",
          url: "https://github.com/dependabot/dependabot-core",
        },
        manifests: {
          "package-lock.json": {
            name: "package-lock.json",
            file: {
              source_location: "src/package-lock.json",
            },
            resolved: {
              "@actions/core": {
                package_url: "pkg:/npm/%40actions/core@1.1.9",
                dependencies: [
                  "@actions/http-client",
                ],
              },
              "@actions/http-client": {
                package_url: "pkg:/npm/%40actions/http-client@1.0.7",
                dependencies: [
                  "tunnel",
                ],
              },
              tunnel: {
                package_url: "pkg:/npm/tunnel@0.0.6",
              },
            },
          },
        }
      )
    end

    it "correctly submits data to create a snapshot" do
      client = DependencyGraphSnapshotsClientStub.with_result(result: :RESULT_ACCEPTED, msg: "snapshot created")
      response = described_class.new(client: client).create_dependabot_snapshot(gh_repo_id: 999, payload: payload)
      expect(response).to be(true)
    end

    it "handles errors returned from service" do
      client = DependencyGraphSnapshotsClientStub.new(DependencyGraphSnapshotsClientStub::PATH) do
        [
          500,
          { "Content-Type" => "application/json" },
          Twirp::Encoding.encode_json(Twirp::Error.internal("service failure").to_h),
        ]
      end

      expect do
        described_class.new(client: client).create_dependabot_snapshot(gh_repo_id: 999, payload: payload)
      end.to raise_error(DependencyGraph::Snapshots::Error, "internal - service failure")
    end

    context "processing snapshot result values" do
      # DS-API uses accepted and success to convey whether a snapshot was merely saved
      # or if it updated the 'canonical' state; Dependabot doesn't care which about this.
      let(:success_results) do
        %i(
          RESULT_ACCEPTED
          RESULT_SUCCESS
        )
      end

      # This will be raised if the payload has encoding problems. Since Dependabot is
      # handling snapshots programmatically generated by code we control in Core,
      # this will likely be a bug.
      let(:error_results) do
        %i(
          RESULT_INVALID
        )
      end

      # These values are part of the DS-API Twirp contract that we do not expect to
      # receive. Either should be treated as a programming error.
      let(:unexpected_results) do
        %i(
          RESULT_UNKNOWN
          RESULT_REMOVED
        )
      end

      it "returns true for any successful result" do
        success_results.each do |result|
          client = DependencyGraphSnapshotsClientStub.with_result(result: result, msg: "snapshot created")
          response = described_class.new(client: client).create_dependabot_snapshot(gh_repo_id: 999, payload: payload)
          expect(response).to be(true)
        end
      end

      it "raises DependencyGraph::Snapshots::InvalidSnapshotError for any error result" do
        error_results.each do |result|
          client = DependencyGraphSnapshotsClientStub.with_result(result: result, msg: "snapshot is full of ants")

          expect do
            described_class.new(client: client).create_dependabot_snapshot(gh_repo_id: 999, payload: payload)
          end.to raise_error(DependencyGraph::Snapshots::InvalidSnapshotError, "snapshot is full of ants")
        end
      end

      it "raises DependencyGraph::Snapshots::Error for any unexpected result" do
        unexpected_results.each do |result|
          client = DependencyGraphSnapshotsClientStub.with_result(result: result, msg: "what's burning?")

          expect do
            described_class.new(client: client).create_dependabot_snapshot(gh_repo_id: 999, payload: payload)
          end.to raise_error(
            DependencyGraph::Snapshots::Error,
            "unexpected snapshot response: '#{result}' - what's burning?"
          )
        end
      end
    end
  end
end
